// Supplied Task B checks. Students do not edit this file.
// This file compiles after you write Lab and Exam in grade_item.h.
#include <cmath>
#include <iostream>
#include <sstream>
#include <string>
#include "../grade_item.h"

bool report(const char* name, bool ok)
{
    std::cout << (ok ? "PASS " : "FAIL ") << name << std::endl;
    return ok;
}

bool same(double a, double b)
{
    return std::fabs(a - b) < 1e-9;
}

// Runs item.print() through a base reference and returns what it printed.
std::string printed(const GradeItem& item)
{
    std::ostringstream text;
    std::streambuf* old = std::cout.rdbuf(text.rdbuf());
    item.print();
    std::cout.rdbuf(old);
    return text.str();
}

// Calls finalPoints() through a base reference.
double pointsThroughBase(const GradeItem& item)
{
    return item.finalPoints();
}

bool checkLine(const std::string& expected, const std::string& actual)
{
    if (expected == actual)
        return true;
    std::cout << "  expected: " << expected;
    std::cout << "  printed:  " << actual;
    return false;
}

int main()
{
    bool all = true;

    Lab onTime("Lab 1", 18, 20, 0);
    Lab oneDay("Lab 2", 18, 20, 1);
    Lab twoDays("Lab 3", 18, 20, 2);
    Lab nineDays("Lab 4", 18, 20, 9);
    Lab tenDays("Lab 5", 18, 20, 10);
    Lab twelveDays("Lab 6", 18, 20, 12);
    Lab negativeDays("Lab 7", 18, 20, -3);
    if (!report("B01 Lab late penalty",
        same(onTime.finalPoints(), 18) && same(oneDay.finalPoints(), 16.2) &&
        same(twoDays.finalPoints(), 14.4) && same(nineDays.finalPoints(), 1.8) &&
        same(tenDays.finalPoints(), 0) && same(twelveDays.finalPoints(), 0) &&
        same(negativeDays.finalPoints(), 18))) all = false;

    Exam midterm("Midterm", 78, 100, 5);
    Exam exactCap("Exam 2", 95, 100, 5);
    Exam overCap("Exam 3", 98, 100, 5);
    Exam noCurve("Exam 4", 61.5, 100, 0);
    Exam negativeCurve("Exam 5", 78, 100, -4);
    if (!report("B02 Exam curve with a maximum",
        same(midterm.finalPoints(), 83) && same(exactCap.finalPoints(), 100) &&
        same(overCap.finalPoints(), 100) && same(noCurve.finalPoints(), 61.5) &&
        same(negativeCurve.finalPoints(), 78))) all = false;

    Lab tooHigh("Lab 8", 25, 20, 0);
    Exam tooLow("Exam 6", -10, 100, 5);
    if (!report("B03 base constructor keeps earned in [0, possible]",
        tooHigh.getName() == "Lab 8" && same(tooHigh.getEarned(), 20) &&
        tooHigh.getPossible() == 20 && same(tooLow.getEarned(), 0) &&
        same(tooLow.finalPoints(), 5))) all = false;

    if (!report("B04 finalPoints through a GradeItem reference",
        same(pointsThroughBase(twoDays), 14.4) &&
        same(pointsThroughBase(overCap), 100))) all = false;

    bool lines = true;
    lines = checkLine("Lab 1: 18.0 / 20 (on time)\n", printed(onTime)) && lines;
    lines = checkLine("Lab 2: 16.2 / 20 (1 day late)\n", printed(oneDay)) && lines;
    lines = checkLine("Lab 3: 14.4 / 20 (2 days late)\n", printed(twoDays)) && lines;
    lines = checkLine("Lab 5: 0.0 / 20 (10 days late)\n", printed(tenDays)) && lines;
    lines = checkLine("Midterm: 83.0 / 100 (curve 5)\n", printed(midterm)) && lines;
    lines = checkLine("Exam 4: 61.5 / 100 (no curve)\n", printed(noCurve)) && lines;
    if (!report("B05 print through a GradeItem reference", lines)) all = false;

    return all ? 0 : 1;
}
